from .ttitrace import TtiTrace
import re
import pkg_resources
import six


class Fsm3FddTtiTrace(TtiTrace):
    KEY_PARAMS = {'port': 'P',
                  'ip_addr': 'n',
                  'task': 't',
                  'filesize': 'm',
                  'prefix': 'o',
                  'duration': 'u'}

    def __init__(self, host_ip, ssh_username, ssh_password, ssh_prompt, ssh_port, stream_path,
                 tracer_path, ip_addr, timeout, log_path, sw_version, cells_sw_type):
        super(Fsm3FddTtiTrace, self).__init__(host_ip, ssh_username, ssh_password, ssh_prompt,
                                              ssh_port, stream_path, tracer_path, ip_addr,
                                              timeout, log_path, sw_version, cells_sw_type)
        self._ip_addr = ip_addr
        self._started = False

    def start_tti_stream(self, core, param):
        """Start ttiStream with provided params
        """
        if self._started:
            raise Exception('Tti Stream already started.')
        if 'ip_addr' not in param:
            param['ip_addr'] = self._ip_addr
        string_params = self._convert_to_params(param)
        cmd = 'cd {};sudo {} -c {} {}'.format(self._log_path, self._stream_path, core, string_params)
        self._executor.write_to_shell("{}\n".format(cmd.strip()))
        self._output = self._executor.read_until_regexp('Press Return to stop')
        if "ERR" in self._output:
            self._executor.write_to_shell('\n')
            self._started = False
            raise Exception(self._output)
        else:
            self._started = True

    def stop_tti_stream(self, lrc=None):
        """Stop running ttiStream
        """
        if not self._started:
            raise Exception('There is no started ttiStream')
        self._executor.write_to_shell('\n')
        self._started = False
        out = self._get_created_dat_file()
        self._log_files.extend(out)
        return out

    def stop_tti_stream_and_convert_to_text(self, nb, ext='txt', lrc=None):
        """Stop running ttiStream and convert dat files to txt
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension
        :return list:                   List of successfully converted txt file
        """
        dat_files = self.stop_tti_stream()
        return list(filter(None, [self.convert_dat_to_text(source=file, destination=None, nb=nb, ext=ext) for file in dat_files]))

    def convert_dat_to_text(self, source, destination, nb, ext='txt'):
        """Converts source dat file to readable text file
        :param source string:           Input dat file name
        :param destination string:      Output txt file name
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension, ignored when destination is given
        :return string:                 Output txt file or empty string if txt file not created
        """
        destination = destination or "{}.{}".format(source, ext)
        cmd = 'cd {};sudo {} --decode {} --output {} {}'.format(self._log_path, self._tracer_path, source, destination,
                                                                '-nb' if nb else '')
        out = self._executor.run(cmd.strip())
        output = self._validate_ouput_file_created(out)
        if output:
            self._log_files.append(output)
        return output

    def get_tti_dl_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:                TTI DL Node
        """
        return self._get_node(lcr, table='MACDLTTI')

    def get_tti_ul_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:         TTI UL Node
        """
        return self._get_node(lcr, table='MACULTTI')

    def _get_default_stream_path(self):
        stream_path = '{}/{}'.format(pkg_resources.resource_filename(__name__, "resources"), 'ttiStream')
        return stream_path

    def _get_default_tracer_path(self):
        tracer_name = 'tti_trace_parser_wmp-linux.exe'
        tracer_path = self._find_tracer_path(tracer_name, '/opt/TtiTracer')
        return tracer_path

    def _find_tracer_path(self, name, path):
        try:
            return self._executor.run('find {} -name {}'.format(path, name)).split()[0]
        except Exception:
            raise Exception('Default Ttitracer not found.')

    def _convert_to_params(self, parameters):
        ret = ''
        for key, value in six.iteritems(parameters):
            if 'debug_level' == key:
                ret = '{} -{}'.format(ret, 'D' * value)
            else:
                ret = '{} -{} {}'.format(ret, self.KEY_PARAMS[key], value)
        return ret.strip()

    def _get_created_dat_file(self):
        out = self._executor.read_shell()
        return self._extract_dat_files_from_output('{}{}'.format(self._output, out))

    def _extract_dat_files_from_output(self, out):
        output_regex = r'Streaming remote file.*local file:(.*\.dat).*'
        lines = out.splitlines()
        p = re.compile(output_regex)
        dat_files = [p.match(line).group(1) for line in lines if p.match(line)]
        if not len(dat_files):
            raise Exception('No Dat File was created.')
        else:
            return self._attach_log_path_to_output(dat_files)

    def _validate_ouput_file_created(self, out):
        lines = out.splitlines()
        p = re.compile(r'Creating ASCII File (\S+)')
        for line in lines:
            m = p.match(line)
            if m:
                return m.group(1)
        return ''

    def _get_node(self, lcr, table):
        cell_info_table = self._get_cell_info_table()
        lcr = lcr or self._get_first_local_cell_resource_id(cell_info_table)
        column = self._get_table_column(cell_info_table, table)
        return self._extract_node(cell_info_table, lcr, column)

    def _get_cell_info_table(self):
        tool_path = '{}/{}'.format(pkg_resources.resource_filename('ta_ttitrace', "resources"), 'getcellmapping')
        self._executor.run('sudo chmod u+x {}'.format(tool_path))
        cmd = 'sudo {} {} 15007'.format(tool_path, self._ip_addr)
        out = self._executor.run(cmd)
        cell_info_table = self._extract_table_from_output(out)
        return cell_info_table

    def _extract_table_from_output(self, out):
        try:
            return re.search(r'lcr lnCel.*\n([\w\s.-]+)$', out, re.MULTILINE).group(0)
        except Exception:
            raise Exception('Table not found.')

    def _get_first_local_cell_resource_id(self, cell_info_table):
        cells = cell_info_table.splitlines()
        return cells[1].split()[0]

    def _get_table_column(self, cell_info_table, table):
        cells = cell_info_table.splitlines()
        tables = cells[0].split()
        for index in range(0, len(tables)):
            if table == tables[index]:
                return index
        raise Exception("{} did not match any table name".format(table))

    def _extract_node(self, cell_info_table, lcr, node):
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[0] == lcr:
                return cell.split()[node][:6]
        raise Exception('{} did not match any local cell resource'.format(lcr))


class Fsm3TddTtiTrace(TtiTrace):
    KEY_PARAMS = {'port': 'P',
                  'ip_addr': 'n',
                  'task': 't',
                  'filesize': 'm',
                  'prefix': 'o',
                  'duration': 'u'}

    def __init__(self, host_ip, ssh_username, ssh_password, ssh_prompt, ssh_port, stream_path,
                 tracer_path, ip_addr, timeout, log_path, sw_version, cells_sw_type):
        super(Fsm3TddTtiTrace, self).__init__(host_ip, ssh_username, ssh_password, ssh_prompt,
                                              ssh_port, stream_path, tracer_path, ip_addr,
                                              timeout, log_path, sw_version, cells_sw_type)
        self._ip_addr = ip_addr
        self._started = False

    def start_tti_stream(self, core, param):
        """Start ttiStream with provided params
        """
        if self._started:
            raise Exception('Tti Stream already started.')
        if 'ip_addr' not in param:
            param['ip_addr'] = self._ip_addr
        string_params = self._convert_to_params(param)
        cmd = 'cd {};sudo {} -c {} -x 4 {}'.format(self._log_path, self._stream_path, core, string_params)
        self._executor.write_to_shell("{}\n".format(cmd.strip()))
        self._output = self._executor.read_until_regexp('Press Return to stop')
        if "ERR" in self._output:
            self._executor.write_to_shell('\n')
            self._started = False
            raise Exception(self._output)
        else:
            self._started = True

    def stop_tti_stream(self, lrc=None):
        """Stop running ttiStream
        """
        if not self._started:
            raise Exception('There is no started ttiStream')
        self._executor.write_to_shell('\n')
        self._started = False
        out = self._get_created_dat_file()
        self._log_files.extend(out)
        return out

    def stop_tti_stream_and_convert_to_text(self, nb, ext='txt', lrc=None):
        """Stop running ttiStream and convert dat files to txt
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension
        :return list:                   List of successfully converted txt file
        """
        dat_files = self.stop_tti_stream()
        return list(filter(None, [self.convert_dat_to_text(source=file, destination=None, nb=nb, ext=ext) for file in dat_files]))

    def convert_dat_to_text(self, source, destination, nb, ext='txt'):
        """Converts source dat file to readable text file
        :param source string:           Input dat file name
        :param destination string:      Output txt file name
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension, ignored when destination is given
        :return string:                 Output txt file or empty string if txt file not created
        """
        destination = destination or "{}.{}".format(source, ext)
        cmd = 'cd {};sudo {} {} {}'.format(self._log_path, self._tracer_path, source, destination)
        out = self._executor.run(cmd.strip())
        if re.search('parse complete.', out):
            output_file = self._attach_log_path_if_not_absolute(destination)
            self._log_files.append(output_file)
            return output_file
        return ''

    def get_tti_dl_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:                TTI DL Node
        """
        return self._get_node(lcr, table='MACDLTTI')

    def get_tti_ul_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:         TTI UL Node
        """
        return self._get_node(lcr, table='MACULTTI')

    def _get_default_stream_path(self):
        stream_name = 'ttiStream'
        stream_path = '{}/{}'.format(pkg_resources.resource_filename(__name__, "resources"), stream_name)
        return stream_path

    def _get_default_tracer_path(self):
        tracer_name = 'DevC_tti_trace_parser_64'
        tracer_path = self._find_tracer_path(tracer_name, '/opt/TtiTracer')
        return tracer_path

    def _find_tracer_path(self, name, path):
        try:
            return self._executor.run('find {} -name {}'.format(path, name)).split()[0]
        except Exception:
            raise Exception('Default Ttitracer not found.')

    def _convert_to_params(self, parameters):
        ret = ''
        for key, value in six.iteritems(parameters):
            if 'debug_level' == key:
                ret = '{} -{}'.format(ret, 'D' * value)
            else:
                ret = '{} -{} {}'.format(ret, self.KEY_PARAMS[key], value)
        return ret.strip()

    def _get_created_dat_file(self):
        out = self._executor.read_shell()
        return self._extract_dat_files_from_output('{}{}'.format(self._output, out))

    def _extract_dat_files_from_output(self, out):
        output_regex = r'Streaming remote file.*local file:(.*\.dat).*'
        dat_files = []
        lines = out.splitlines()
        p = re.compile(output_regex)
        for line in lines:
            m = p.match(line)
            if m:
                dat_files.append(m.group(1))
        if not len(dat_files):
            raise Exception('No Dat File was created.')
        else:
            return self._attach_log_path_to_output(dat_files)

    def _get_node(self, lcr, table):
        cell_info_table = self._get_cell_info_table()
        lcr = lcr or self._get_first_local_cell_resource_id(cell_info_table)
        column = self._get_table_column(cell_info_table, table)
        return self._extract_node(cell_info_table, lcr, column)

    def _get_cell_info_table(self):
        tool_path = '{}/{}'.format(pkg_resources.resource_filename('ta_ttitrace', "resources"), 'getcellmapping')
        self._executor.run('sudo chmod u+x {}'.format(tool_path))
        cmd = 'sudo {} {} 15007'.format(tool_path, self._ip_addr)
        out = self._executor.run(cmd)
        cell_info_table = self._extract_table_from_output(out)
        return cell_info_table

    def _extract_table_from_output(self, out):
        try:
            return re.search(r'lcr lnCel.*\n([\w\s.-]+)$', out, re.MULTILINE).group(0)
        except Exception:
            raise Exception('Table not found.')

    def _get_first_local_cell_resource_id(self, cell_info_table):
        cells = cell_info_table.splitlines()
        return cells[1].split()[0]

    def _get_table_column(self, cell_info_table, table):
        cells = cell_info_table.splitlines()
        tables = cells[0].split()
        for index in range(0, len(tables)):
            if table == tables[index]:
                return index
        raise Exception("{} did not match any table name".format(table))

    def _extract_node(self, cell_info_table, lcr, node):
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[0] == lcr:
                return cell.split()[node][:6]
        raise Exception('{} did not match any local cell resource'.format(lcr))
